const NODE_TXT=['自立し、自分の直感と勇気を信じることを学び、人のためだけに生きるのをやめていきます。','自分なりの安定と価値を築くことを学び、危機や他人の資源への依存を手放していきます。','好奇心を持ち、耳を傾け、多様な交流をすることを学び、「答えはすべてわかっている」という思い込みを手放していきます。','内面と家庭を大切にすることを学び、成功や体面だけを追うのをやめていきます。','勇気を出して自分を表現し、舞台に立つことを学び、集団に隠れる安心感を手放していきます。','現実的に、人の役に立ち、細部を大切にすることを学び、現実から逃げる傾向を手放していきます。','協力し、人の話に耳を傾けることを学び、何でも自分ひとりでやろうとするのをやめていきます。','深いつながりと分かち合いを学び、物質的な安定への執着を手放していきます。','直感と、より大きな意味を信じることを学び、情報や細部への不安を手放していきます。','責任を引き受け、仕事を築くことを学び、家への過度な依存を手放していきます。','仲間のために貢献し、自分の個性を受け入れることを学び、個人としての輝きへの欲求を手放していきます。','信頼し、手放し、スピリチュアルなものに開くことを学び、コントロールしすぎることや細かすぎることを手放していきます。'];
const HOUSE=['自己イメージと第一印象','お金・持ち物・自己価値','コミュニケーション・学び・兄弟姉妹','家庭・ルーツ・心の拠りどころ','恋愛・遊び・創作・子ども','日々の仕事・生活リズム・健康','パートナー・協力・一対一の関係','共有する資源・親密さ・深い変化','遠い旅・信念・学問','仕事・社会的地位・世間からの評価','友人・仲間・未来の願い','無意識・ひとりの時間・見えないもの'];
const PN={Sun:'太陽',Moon:'月',Mercury:'水星',Venus:'金星',Mars:'火星',Jupiter:'木星',Saturn:'土星',Uranus:'天王星',Neptune:'海王星',Pluto:'冥王星',Node:'ノースノード',ASC:'アセンダント',MC:'MC'};
const THEME={Sun:'自分らしさ',Moon:'感情',Mercury:'思考',Venus:'愛情',Mars:'行動力',Jupiter:'成長',Saturn:'責任',Uranus:'変革',Neptune:'夢',Pluto:'変容',ASC:'第一印象',MC:'仕事の方向性'};
const ASP=[['コンジャンクション','二つの力が結びつき、互いを強め合う'],['セクスタイル','小さな助け合い。自分から動けば支え合える'],['スクエア','引っぱり合って行き詰まるが、成長のきっかけにもなる'],['トライン','自然とスムーズ。無理なく協力できる'],['オポジション','二つの間で揺れ動き、バランスを学ぶ'],['クインカンクス','かみ合いにくく、少しずつ調整し続けることを求められる']];
const DIG={Sun:{d:[4],e:[0],x:[10],f:[6]},Moon:{d:[3],e:[1],x:[9],f:[7]},Mercury:{d:[2,5],e:[5],x:[8,11],f:[11]},Venus:{d:[1,6],e:[11],x:[7,0],f:[5]},Mars:{d:[0,7],e:[9],x:[6,1],f:[3]},Jupiter:{d:[8,11],e:[3],x:[2,5],f:[9]},Saturn:{d:[9,10],e:[6],x:[3,4],f:[0]},Uranus:{d:[10],e:[],x:[4],f:[]},Neptune:{d:[11],e:[],x:[5],f:[]},Pluto:{d:[7],e:[],x:[1],f:[]}};
const DIG_TXT={d:['ドミサイル（本来の座）','自分のホームにいて、エネルギーが純粋で、自然に発揮されます。'],e:['エグザルテーション（高揚）','貴賓のようにもてなされ、長所が大きく引き出されます。'],x:['デトリメント（障害）','なじみのない環境にいるため、手間のかかるやり方や、一風変わったやり方で表現する必要があります。'],f:['フォール（失墜）','エネルギーが抑えられがちで、経験と練習を重ねてこそ発揮できます。']};
const RULER=['Mars','Venus','Mercury','Moon','Sun','Mercury','Venus','Mars','Jupiter','Saturn','Saturn','Jupiter'];
const MODERN={7:'Pluto',10:'Uranus',11:'Neptune'};
const TRANSIT={Jupiter:'この一年、この分野でチャンスや助けてくれる人、成長に恵まれやすくなります。',Saturn:'この二、三年、この分野では現実と向き合い、ルールを作ることが求められます。大変ですが、確かな成果が残ります。',Uranus:'ここ数年、この分野に思いがけない変化が起き、新しい自由ももたらされます。',Neptune:'この分野の境界があいまいになり、ひらめきが増える一方、混乱や非現実的な期待には注意が必要です。',Pluto:'この分野は深く長期的な変容の最中にあり、古いパターンが根本から刷新されます。'};
const HIT_TONE={conj:'強く始動させる',good:'追い風になる',bad:'試練と調整をもたらす'};

function dignity(k,s){const g=DIG[k];if(!g)return null;const out=[];for(const t of ['d','e','x','f'])if(g[t].includes(s))out.push(t);return out.length?out:null;}

function readWest(W,E){
  const P=W.pos;let o=[];
  const s=k=>signOf(k==='ASC'?W.asc:P[k].lon);
  const sun=s('Sun'),moon=s('Moon'),asc=s('ASC'),ven=s('Venus');
  const els=[...new Set([sun,moon,asc].map(i=>EL[i%4]))];
  const opp=(els.includes('fire')&&els.includes('water'))||(els.includes('earth')&&els.includes('air'));
  let mix;
  if(els.length===1)mix=`内と外が一致していて、${ELQ[els[0]]}がとても際立つ人`;
  else mix=`${els.map(e=>ELQ[e]).join(els.length===2?'と':'・')}を併せ持つ、${opp?'独特な矛盾を抱えた人':'多面的な性格の人'}`;
  o.push(h3('星座の読み解き'));
  o.push(p(`この組み合わせ（太陽${SG[sun]}、アセンダント${SG[asc]}、月${SG[moon]}、金星${SG[ven]}）は、外側は${OUTER[asc]}、内側は${INNER[moon]}、${mix}です。`));
  if(STA())o.push(p(STA().ascSun[asc][sun]));
  if(STW())o.push(p(STW().sunMoon[sun][moon]));
  let n=1;const basic=o;
  for(const k of ['ASC','Sun','Moon','Venus','Mercury','Mars']){
    const [title,pname,data]=ROLE[k];const i=s(k);
    if(k==='Mercury'){o=[];o.push(h3('さらに星座の側面','w-more'));}
    o.push(h4(`${n++}. ${title}：${pname}・${SG[i]}`));
    o.push(ul(data[i].map(([a,b])=>pt(a,b))));
    if(STW()&&STW().scenes[k]&&STW().scenes[k][i])o.push(scene(STW().scenes[k][i]));
  }
  /* ハウス */
  o.push(h3('惑星のハウス','w-houses'));
  o.push(ul(['Sun','Moon','Mercury','Venus','Mars','Jupiter','Saturn'].map(k=>pt(`${PN[k]}は第${P[k].house}ハウス`,`${PN[k]}が表す${THEME[k]}は、主に「${HOUSE[P[k].house-1]}」の分野で発揮されます。`))));
  /* 品位 */
  const dg=[];
  for(const k of E.PK){const d=dignity(k,s(k));if(d)dg.push(pt(`${PN[k]}・${SG[s(k)]}：${d.map(t=>DIG_TXT[t][0]).join('、')}`,d.map(t=>DIG_TXT[t][1]).join('')));}
  o.push(h3('惑星の力の状態（品位）','w-dignity'));
  o.push(dg.length?ul(dg):p('ドミサイル、エグザルテーション、デトリメント、フォールに当たる惑星はなく、どの惑星も中立的な力の状態です。'));
  /* ルーラー */
  const ar=RULER[asc],mr=MODERN[asc];
  const ruleLine=k=>`${SG[s(k)]}・第${P[k].house}ハウス`;
  o.push(h3('ルーラーとハウスの支配星','w-rulers'));
  o.push(p(`アセンダント${SG[asc]}のルーラー（支配星）は<b>${PN[ar]}</b>（${ruleLine(ar)}）${mr?`で、現代占星術では<b>${PN[mr]}</b>も共同支配星とされます（${ruleLine(mr)}）`:'です'}。ルーラーのある場所に、人生の重心は引き寄せられがちです。あなたのエネルギーは自然と「${HOUSE[P[ar].house-1]}」へ向かいます。`));
  const rows=W.houses.map((c,i)=>{const sg=signOf(c),r=RULER[sg];const own=P[r].house===i+1;return `<tr><td class="mono">${i+1}</td><td>${SG[sg]} ${fmt(c)}</td><td>${PN[r]}${MODERN[sg]?`／${PN[MODERN[sg]]}`:''}</td><td class="mono">${P[r].house}</td><td>${own?`支配星が自分のハウスに戻っています。「${HOUSE[i]}」のことはあなた自身が主導し、エネルギーが集中してストレートに働きます。`:`「${HOUSE[i]}」のテーマは、「${HOUSE[P[r].house-1]}」を通して実現されます。`}</td></tr>`;});
  if(W.equal)o.push(p('出生地の緯度がとても高く、プラシーダス・ハウスシステムが成り立たないため、イコールハウス（アセンダントから30°ずつ区切る方式）を使っています。'));
  o.push(`<div class="tablewrap"><table><thead><tr><th>ハウス</th><th>カスプ</th><th>支配星</th><th>在住ハウス</th><th>読み解き</th></tr></thead><tbody>${rows.join('')}</tbody></table></div>`);
  /* アスペクト */
  const personal=['Sun','Moon','Mercury','Venus','Mars','Jupiter','Saturn'];
  const keyAsp=W.asp.filter(a=>a.orb<=4&&(personal.includes(a.a)||personal.includes(a.b))).slice(0,10);
  o.push(h3('主なアスペクト','w-aspects'));
  o.push(keyAsp.length?ul(keyAsp.map(a=>pt(`${PN[a.a]}と${PN[a.b]}の${ASP[a.t][0]}（オーブ ${a.orb.toFixed(1)}°）`,(STW()&&STW().aspects[`${a.a}-${a.b}`]&&STW().aspects[`${a.a}-${a.b}`][a.t])||`${THEME[a.a]}と${THEME[a.b]}：${ASP[a.t][1]}。`))):p('オーブ4°以内の主なアスペクトはありません。'));
  /* 図形 */
  const pats=patterns(W,E);
  o.push(h3('アスペクトの図形とステリウム','w-patterns'));
  o.push(pats.length?ul(pats):p('グランドトライン、Tスクエア、グランドクロス、ヨッド、ステリウムといった特別な図形はなく、エネルギーは比較的均等に分布しています。'));
  /* エレメントとクオリティ */
  const cnt={fire:0,earth:0,air:0,water:0},md=[0,0,0];
  for(const k of E.PK){const i=s(k);cnt[EL[i%4]]++;md[i%3]++;}
  const MISS={fire:'火がない：行動の前にためらいがちです。意識して自分に火をつけ、締め切りを決めましょう。',earth:'地がない：物事を形にすることやお金の管理には工夫が必要です。計画を書き出すととても役立ちます。',air:'風がない：一歩引いて考えることが少なめです。人と話し合い、本を読むことで全体像が見えやすくなります。',water:'水がない：感情を表に出すことが少なめです。気持ちを言葉にする練習をすると、関係がもっと近くなります。'};
  const MD=[['活動宮','新しいことを始めるのが好きで、スタートを切るのが得意です','始める力'],['不動宮','根気があり粘り強い一方、変化は苦手です','粘り強さ'],['柔軟宮','適応力があり融通がききますが、気が散りやすいです','適応力']];
  const mx=Math.max(...md),tops=[0,1,2].filter(i=>md[i]===mx);
  const el=[`十天体のエレメント分布：${EL.map(e=>`${ELN[e]} ${cnt[e]}`).join('、')}。クオリティの分布：${MD.map((m,i)=>`${m[0]} ${md[i]}`).join('、')}。`,tops.length===1?`${MD[tops[0]][0]}の星座がいちばん多く、${MD[tops[0]][1]}。`:`${tops.map(i=>MD[i][0]).join('と')}の星座が同じ数で、${tops.map(i=>MD[i][2]).join('と')}を併せ持っています。`];
  EL.filter(e=>cnt[e]===0).forEach(e=>el.push(MISS[e]));
  EL.filter(e=>cnt[e]>=5).forEach(e=>el.push(`${ELN[e]}のエレメントが特に多い（${cnt[e]}個）：${ELQ[e]}があなたのいちばん鮮やかな基調です。`));
  const up=E.PK.filter(k=>P[k].house>=7).length,east=E.PK.filter(k=>[10,11,12,1,2,3].includes(P[k].house)).length;
  el.push(`半球の分布：地平線より上に${up}個、下に${10-up}個。${up>=6?'人生のエネルギーは外の世界や社会の舞台に向かいがちです':up<=4?'人生のエネルギーは内面・家庭・プライベートに向かいがちです':'内と外はほぼバランスがとれています'}。東半球に${east}個、西半球に${10-east}個。${east>=6?'自分で方向を決め、自ら切り開くタイプです':east<=4?'人との協力を通して自分を実現するタイプです':'自主性と協調性はほぼバランスがとれています'}。`);
  o.push(h3('エレメント・クオリティ・半球','w-balance'));o.push(ul(el));
  /* ノースノード */
  const nd=signOf(P.Node.lon);
  o.push(h3('人生の方向性（ノースノード）','w-node'));
  o.push(p(`ノースノードは${SG[nd]}・第${P.Node.house}ハウス：${NODE_TXT[nd]}この人生で成長していく方向は「${HOUSE[P.Node.house-1]}」にあります。`));
  /* トランジット */
  const tr=E.transits(W,new Date());
  o.push(h3('現在のトランジット','w-transits'));
  o.push(ul(tr.map(t=>{const hit=t.hits.map(x=>`ネイタルの${PN[x.n]}と${ASP[x.t][0]}（オーブ ${x.orb.toFixed(1)}°、${HIT_TONE[x.tone]}）`).join('、');
    return pt(`${PN[t.k]}が${SG[signOf(t.lon)]}・ネイタルの第${t.house}ハウスを運行中`,`${HOUSE[t.house-1]}の面で：${TRANSIT[t.k]}${hit?`現在、${hit}。`:''}`);})));
  /* あなたの物語（ルールでつなぐ） */
  const ws=[];
  if(STA())ws.push(`まずは外側から見てみましょう。${STA().ascSun[asc][sun]}`);
  if(STW())ws.push(`次に、内側に目を向けてみます。${STW().sunMoon[sun][moon]}`);
  if(STW()){const mars=s('Mars'),strip=t=>(t||'').replace(/^たとえば、?/,'');ws.push(`恋愛の場面では、金星${SG[ven]}のあなたはこんなふうです。${strip(STW().scenes.Venus[ven])}ぶつかり合ったときや何かを勝ち取りたいとき、火星${SG[mars]}のあなたはこう動きます。${strip(STW().scenes.Mars[mars])}`);}
  {const dom=EL.filter(e=>cnt[e]===Math.max(...EL.map(x=>cnt[x])));const miss=EL.filter(e=>cnt[e]===0);
   ws.push(`チャート全体を広げてみると、チャートルーラーの${PN[ar]}は第${P[ar].house}ハウスにあり、人生の重心は「${HOUSE[P[ar].house-1]}」へと引き寄せられがちです。十天体の中では${dom.map(e=>ELN[e]).join('・')}のエレメントがいちばん多く、${dom.map(e=>ELQ[e]).join('と')}があなたの基調になっています${miss.length?`。一方で${miss.map(e=>ELN[e]).join('・')}のエレメントは一つもなく、そこは意識して育てていきたい力です`:''}。`);}
  {const a=keyAsp[0];const t=a&&STW()&&STW().aspects[`${a.a}-${a.b}`]&&STW().aspects[`${a.a}-${a.b}`][a.t];
   if(t)ws.push(`あなたのチャートでいちばんタイトなアスペクトは、${PN[a.a]}と${PN[a.b]}の${ASP[a.t][0]}（オーブ ${a.orb.toFixed(1)}°）です。これはあなたの中ではっきり表れています。${t}`);}
  {const hit=tr.filter(x=>['Saturn','Uranus','Neptune','Pluto'].includes(x.k)).flatMap(x=>x.hits.filter(h=>['Sun','Moon','ASC'].includes(h.n)).map(h=>({...h,k:x.k}))).sort((a,b)=>a.orb-b.orb)[0];
   if(hit)ws.push(`そしてここ数年、${PN[hit.k]}があなたのネイタルの${PN[hit.n]}と${ASP[hit.t][0]}を形成しています（${HIT_TONE[hit.tone]}）。${{Saturn:'現実と向き合い、土台を固めることが求められる時期です。楽ではありませんが、本当に自分のものと言える成果が残ります。',Uranus:'これまでの枠を壊したくなり、暮らしに急な方向転換が起きるかもしれません。好奇心に従って進むと、うれしい発見があることが多いでしょう。',Neptune:'人生に対するイメージが変わりつつあります。ひらめきが増える一方で物事が見えにくくもなるので、大事な決断は事実をよく確かめてから。',Pluto:'深いところから生まれ変わっていく時期です。古い自分が少しずつ退場し、新しい力が育ってきています。'}[hit.k]}`);}
  if(ws.length)o.unshift(h3('あなたの物語','w-story'),...ws.map(p));
  return{basic:basic.join(''),adv:o.join('')};
}
function patterns(W,E){
  const P=W.pos,K=E.PK,out=[],L=k=>P[k].lon,sep=E.sep;
  const near=(a,b,ang,orb)=>Math.abs(sep(L(a),L(b))-ang)<=orb;
  const bySign={},byHouse={};
  for(const k of K){(bySign[signOf(L(k))]=bySign[signOf(L(k))]||[]).push(k);(byHouse[P[k].house]=byHouse[P[k].house]||[]).push(k);}
  for(const s in bySign)if(bySign[s].length>=3)out.push(pt(`${SG[s]}のステリウム（${bySign[s].map(k=>PN[k]).join('、')}）`,`エネルギーが強く集中し、${SG[s]}の性質があなたのとても鮮やかなトレードマークになります。`));
  for(const h in byHouse)if(byHouse[h].length>=3)out.push(pt(`第${h}ハウスのステリウム（${byHouse[h].map(k=>PN[k]).join('、')}）`,`人生の多くの注意が「${HOUSE[h-1]}」に向けられます。`));
  for(let i=0;i<K.length;i++)for(let j=i+1;j<K.length;j++)for(let k=j+1;k<K.length;k++){
    const a=K[i],b=K[j],c=K[k];
    if(near(a,b,120,7)&&near(b,c,120,7)&&near(a,c,120,7))out.push(pt(`グランドトライン（${PN[a]}、${PN[b]}、${PN[c]}）`,'才能がなめらかに流れ、物事を難なくこなせますが、居心地のいい場所に安住しがちなので、意識して自分に挑戦しましょう。'));
  }
  for(let i=0;i<K.length;i++)for(let j=i+1;j<K.length;j++){
    const a=K[i],b=K[j];if(!near(a,b,180,8))continue;
    for(const c of K){if(c===a||c===b)continue;if(near(a,c,90,7)&&near(b,c,90,7))out.push(pt(`Tスクエア（${PN[a]}と${PN[b]}がオポジション、${PN[c]}が頂点）`,`プレッシャーは${PN[c]}が表す${THEME[c]}に集中し、この緊張があなたを前へ進めるエンジンになります。`));}
  }
  for(let i=0;i<K.length;i++)for(let j=i+1;j<K.length;j++){
    const a=K[i],b=K[j];if(!near(a,b,60,4))continue;
    for(const c of K){if(c===a||c===b)continue;if(near(a,c,150,2.5)&&near(b,c,150,2.5))out.push(pt(`ヨッド（${PN[a]}と${PN[b]}が${PN[c]}を指す）`,`特別な使命感が${THEME[c]}に集まり、たえず調整と適応が求められます。`));}
  }
  return [...new Set(out)];
}

/* ===================================================================
   紫微斗数（内部キーは iztro の繁体字のまま）
   =================================================================== */
